<script setup lang="ts">
import { computed, ref } from 'vue';
import SportTabs from './SportTabs.vue';
import SportEventMark from './SportEventMark.vue';
type Event = {id:string;kind:string;side:'home'|'away'|'unknown';period:string|null;minute:number|null;cardLabel:string|null;cardColor:string|null;name:string;relatedName:string|null};
type Team = {name:string;id:string;color:string;hasShield:boolean};
const props=defineProps<{match:{id:string;match_date:string;match_time:string;home_name:string;away_name:string;result:{status:'official'|'provisional';score:{home:number;away:number};shootout:{home:number;away:number};players:Array<{side:'home'|'away';name:string;shirtNumber:number|null}>;events:Event[]}|null};home:Team;away:Team;organizationId:string}>();
const open=ref(false),tab=ref('events');
const players=computed(()=>props.match.result?.players?.length?props.match.result.players:[...new Map((props.match.result?.events||[]).filter(event=>event.name!=='Jugador').map(event=>[`${event.side}:${event.name}`,{name:event.name,side:event.side,shirtNumber:null}])).values()]);
const id=`public-match-${props.match.id}`;
function initials(name:string){return name.split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase();}
function eventName(event:Event){return event.cardLabel||({goal:'Gol',penalty:'Penal',own_goal:'Autogol',yellow:'Amarilla',second_yellow:'Segunda amarilla',red:'Roja',custom_card:'Tarjeta',substitution:'Cambio',incident:'Incidencia',shootout_goal:'Penal convertido',shootout_miss:'Penal fallado'} as Record<string,string>)[event.kind]||'Evento';}
</script>
<template>
  <div class="public-match">
    <button type="button" class="public-match-open" :aria-expanded="open" :aria-controls="`${id}-detail`" @click="open=!open"><div class="public-match-main"><div class="public-match-team"><img v-if="home.hasShield" class="public-match-mark" :src="`/api/v1/public/organizations/${organizationId}/teams/${home.id}/shield`" :alt="`Escudo de ${home.name}`"><span v-else class="public-match-mark placeholder" :style="{background:home.color}">{{ initials(home.name) }}</span><strong>{{ home.name }}</strong></div><span class="public-match-score" :class="{final:match.result?.status==='official'}">{{ match.result?`${match.result.score.home} : ${match.result.score.away}`:match.match_time||'—' }}</span><div class="public-match-team"><img v-if="away.hasShield" class="public-match-mark" :src="`/api/v1/public/organizations/${organizationId}/teams/${away.id}/shield`" :alt="`Escudo de ${away.name}`"><span v-else class="public-match-mark placeholder" :style="{background:away.color}">{{ initials(away.name) }}</span><strong>{{ away.name }}</strong></div></div><div class="public-match-meta"><span>{{ match.result?.status==='official'?'Final':match.result?.status==='provisional'?'Provisional':match.match_date }}</span><span v-if="match.result&&(match.result.shootout.home||match.result.shootout.away)">Penales {{ match.result.shootout.home }} : {{ match.result.shootout.away }}</span><span class="public-match-detail-cue">{{ open?'Cerrar':'Ver partido' }}</span></div></button>
    <div v-if="open" :id="`${id}-detail`" class="public-match-detail"><SportTabs v-model="tab" :tabs="[{key:'events',label:'Eventos',icon:'ball'},{key:'players',label:'Jugadores',icon:'users'}]" :id="id" /><section v-if="tab==='events'" :id="`${id}-events-panel`" role="tabpanel" :aria-labelledby="`${id}-events-tab`"><p v-if="!match.result?.events?.length" class="empty-list">Aún sin eventos públicos.</p><div v-for="event in match.result?.events||[]" :key="event.id" class="sport-event-row"><SportEventMark :kind="event.kind" :color="event.cardColor||undefined" /><div><strong>{{ event.name }}</strong><small>{{ eventName(event) }} · {{ event.side==='home'?home.name:event.side==='away'?away.name:'' }}<template v-if="event.period"> · {{ event.period }}</template><template v-if="event.minute!==null"> · {{ event.minute }} min</template><template v-if="event.relatedName"> · entra {{ event.relatedName }}</template></small></div></div></section><section v-else :id="`${id}-players-panel`" role="tabpanel" :aria-labelledby="`${id}-players-tab`"><p v-if="!players.length" class="empty-list">Sin jugadores publicados.</p><div v-for="player in players" :key="`${player.side}-${player.name}`" class="match-player-row"><span class="standing-team-dot" :style="{background:player.side==='home'?home.color:away.color}"></span><span>{{ player.shirtNumber!==null?`#${player.shirtNumber} · `:'' }}{{ player.name }} <small>· {{ player.side==='home'?home.name:away.name }}</small></span></div></section></div>
  </div>
</template>
